using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using IslandGame;using IslandGame.MapReview;using Object=UnityEngine.Object;
public static class BakeMountZones {
 const string Root="Assets/Island/MountRuntime",Review="Assets/Island/MapMigration",Work="C:/Users/SHK/mount-sunday-playtest-20261108";
 static readonly float[] Lengths={24,28,30,22,54,28,32,26,30,26};
 static Vector3 V(JToken t)=>new Vector3((float)t["x"],(float)t["y"],(float)t["z"]);
 static Mesh Save(Mesh m,string path){var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);Object.DestroyImmediate(m);return old;}AssetDatabase.CreateAsset(m,path);return m;}
