 public static string Prepare(){foreach(string d in new[]{"Scenes","Meshes","Materials","Backgrounds","Data"})Directory.CreateDirectory(Root+"/"+d);AssetDatabase.Refresh();EditorSceneManager.OpenScene("Assets/MountSunday/Review/MountSunday_Exploration_Review.unity");var env=SceneManager.GetActiveScene().GetRootGameObjects().First(g=>g.name.StartsWith("Mount Sunday"));var vv=new List<Vector3>();var nn=new List<Vector3>();var cc=new List<Color>();var uv=new List<Vector2>();var tt=new List<int>();
  foreach(var f in env.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Terrain_")||f.name.StartsWith("Distant_"))){var mesh=f.sharedMesh;var v=mesh.vertices;var n=mesh.normals;var c=mesh.colors;var rows=new SortedDictionary<int,SortedDictionary<int,int>>();for(int i=0;i<v.Length;i++){var w=f.transform.TransformPoint(v[i]);int x=Mathf.RoundToInt(w.x*10),z=Mathf.RoundToInt(w.z*10);if(!rows.TryGetValue(z,out var row))rows[z]=row=new SortedDictionary<int,int>();row[x]=i;}var zs=rows.Keys.ToArray();var map=new List<int[]>();foreach(int zi in Enumerable.Range(0,zs.Length).Where(i=>i%5==0||i==zs.Length-1)){var row=rows[zs[zi]];var xs=row.Keys.ToArray();var ids=new List<int>();foreach(int xi in Enumerable.Range(0,xs.Length).Where(i=>i%5==0||i==xs.Length-1)){int id=row[xs[xi]];var w=f.transform.TransformPoint(v[id]);ids.Add(vv.Count);vv.Add(w);nn.Add(f.transform.localToWorldMatrix.inverse.transpose.MultiplyVector(n[id]).normalized);var col=c.Length>id?c[id]:new Color(.35f,.45f,.25f);col.a=0;cc.Add(col);uv.Add(new Vector2(w.x,w.z));}map.Add(ids.ToArray());}for(int z=0;z<map.Count-1;z++)for(int x=0;x<Math.Min(map[z].Length,map[z+1].Length)-1;x++){Tri(map[z][x],map[z+1][x],map[z][x+1]);Tri(map[z][x+1],map[z+1][x],map[z+1][x+1]);}}
  var output=new Mesh{name="Mount terrain 10m source sampling",indexFormat=IndexFormat.UInt32};output.SetVertices(vv);output.SetNormals(nn);output.SetColors(cc);output.SetUVs(0,uv);output.SetTriangles(tt,0);output.RecalculateBounds();Save(output,Root+"/Meshes/CoarseSource.asset");AssetDatabase.SaveAssets();return "Coarse triangles="+tt.Count/3;
  void Tri(int a,int b,int c){if(Vector3.Cross(vv[b]-vv[a],vv[c]-vv[a]).y<0){int q=b;b=c;c=q;}tt.Add(a);tt.Add(b);tt.Add(c);}
 }
 public static string Zone(int id){var scene=EditorSceneManager.OpenScene(Review+"/Scenes/Zone"+id.ToString("00")+".unity");var zone=scene.GetRootGameObjects().First(g=>g.name.StartsWith("Zone "));var all=JObject.Parse(File.ReadAllText(Review+"/Data/Zones.json"));var definition=all["zones"][id-1];var path=definition["path"].Select(V).Select(p=>zone.transform.TransformPoint(p)).OrderBy(p=>p.x).ToArray();float total=path.Last().x-path.First().x,length=Mathf.Min(Lengths[id-1],total),center=id==1?path.First().x+length/2:id==10?path.Last().x-length/2:(path.First().x+path.Last().x)/2,minX=center-length/2,maxX=center+length/2;
  var selected=new List<Vector3>{Sample(minX)};selected.AddRange(path.Where(p=>p.x>minX&&p.x<maxX));selected.Add(Sample(maxX));Physics.SyncTransforms();for(int i=0;i<selected.Count;i++){var p=selected[i];if(Physics.Raycast(p+Vector3.up*200,Vector3.down,out var h,500,1<<28))p.y=h.point.y;selected[i]=p;}
  float minZ=selected.Min(p=>p.z)-9,maxZ=selected.Max(p=>p.z)+9,step=.5f,ox=Mathf.Floor(minX-3),oz=Mathf.Floor(minZ);int width=Mathf.CeilToInt((maxX+3-ox)/step)+1,height=Mathf.CeilToInt((maxZ-oz)/step)+1;var heights=new List<float>();var valid=new List<int>();int misses=0;
  for(int z=0;z<height;z++)for(int x=0;x<width;x++){var p=new Vector3(ox+x*step,200,oz+z*step);bool hit=Physics.Raycast(p,Vector3.down,out var h,500,1<<28);heights.Add(hit?Mathf.Round(h.point.y*10000)/10000:0);valid.Add(hit?1:0);if(!hit)misses++;}
  var obstacles=new List<object>();var props=zone.transform.Find("Nearby authored props");foreach(Transform g in props){if(!(g.name.StartsWith("tree")||g.name.StartsWith("rock")))continue;var p=g.position;if(p.x<minX-3||p.x>maxX+3||p.z<minZ||p.z>maxZ)continue;float r=g.name.StartsWith("tree")?.4f:.7f;if(g.GetComponentsInChildren<Renderer>().Length>0&&g.name.StartsWith("rock")){var b=g.GetComponentsInChildren<Renderer>()[0].bounds;r=Mathf.Clamp(Mathf.Min(b.extents.x,b.extents.z),.2f,1.5f);}if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(p.x,Sample(p.x).z))>1.3f+r)obstacles.Add(new{x=p.x*100,y=5000+p.z*100,radius=r*100});}
  var data=new{id=id-1,name=(string)definition["name"],mode=(string)definition["mode"],minX=minX*100,maxX=maxX*100,halfWidth=id==5?.50f:(string)definition["mode"]=="quarter"?6f:1.1f,path=selected.Select(p=>new{x=p.x,y=p.y,z=p.z}),terrain=new{originX=ox,originZ=oz,step,width,height,heights,valid},obstacles};string json=JsonConvert.SerializeObject(data);File.WriteAllText(Root+"/Data/Zone"+id.ToString("00")+".json",json);File.WriteAllText(Work+"/evidence/terrain-zone"+id.ToString("00")+".json",json);
  // The far view is captured from the actual map; only its background will be retained at runtime.
  var cam=Object.FindFirstObjectByType<BattleCameraController>().view;var grass=Object.FindFirstObjectByType<MapReviewGrass>();grass.enabled=false;foreach(var r in scene.GetRootGameObjects())if(r!=zone&&r!=cam.transform.root.gameObject)r.SetActive(false);props.gameObject.SetActive(false);zone.transform.Find("Playable ground - original heights").gameObject.SetActive(false);var skirt=zone.transform.Find("Terrain edge skirts");if(skirt)skirt.gameObject.SetActive(false);var far=zone.transform.Find("Distant context - no physics");far.gameObject.SetActive(true);
  cam.transform.SetParent(null,true);cam.transform.position=Sample(center)+Vector3.up*3;cam.farClipPlane=9000;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.55f,.64f,.70f);var cube=new Cubemap(256,TextureFormat.RGB24,true);cube.name="Zone"+id+" baked distant map";if(!cam.RenderToCubemap(cube))throw new Exception("Background capture failed");cube.Apply(true,false);string cp=Root+"/Backgrounds/Zone"+id.ToString("00")+".asset";var prior=AssetDatabase.LoadAssetAtPath<Cubemap>(cp);if(prior){EditorUtility.CopySerialized(cube,prior);Object.DestroyImmediate(cube);cube=prior;}else AssetDatabase.CreateAsset(cube,cp);var sky=new Material(Shader.Find("Island/Mount/BakedSky"));sky.SetTexture("_Tex",cube);sky.SetFloat("_Exposure",1);sky.SetFloat("_Rotation",0);sky=Mat(sky,Root+"/Materials/Sky"+id.ToString("00")+".mat");
  props.gameObject.SetActive(true);zone.transform.Find("Playable ground - original heights").gameObject.SetActive(true);if(skirt)skirt.gameObject.SetActive(true);
  // A small 3D horizon collar covers the near edge; distant terrain is represented by the baked cubemap.
  var coarse=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/Meshes/CoarseSource.asset");var vertices=coarse.vertices;var triangles=coarse.triangles;var subset=new List<int>();var originalCenter=zone.transform.InverseTransformPoint(Sample(center));for(int j=0;j<triangles.Length;j+=3){var p=(vertices[triangles[j]]+vertices[triangles[j+1]]+vertices[triangles[j+2]])/3;if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(originalCenter.x,originalCenter.z))<420){subset.Add(triangles[j]);subset.Add(triangles[j+1]);subset.Add(triangles[j+2]);}}
  var remap=new Dictionary<int,int>();var v2=new List<Vector3>();var n2=new List<Vector3>();var c2=new List<Color>();var u2=new List<Vector2>();var normals=coarse.normals;var colors=coarse.colors;var uvs=coarse.uv;var outIndices=new List<int>();foreach(int old in subset){if(!remap.TryGetValue(old,out int n)){n=v2.Count;remap[old]=n;v2.Add(vertices[old]);n2.Add(normals[old]);c2.Add(colors[old]);u2.Add(uvs[old]);}outIndices.Add(n);}var fm=new Mesh{name="Zone"+id+" horizon collar",indexFormat=IndexFormat.UInt32};fm.SetVertices(v2);fm.SetNormals(n2);fm.SetColors(c2);fm.SetUVs(0,u2);fm.SetTriangles(outIndices,0);fm.RecalculateBounds();far.GetComponent<MeshFilter>().sharedMesh=Save(fm,Root+"/Meshes/Far"+id.ToString("00")+".asset");far.localPosition=Vector3.down*2.5f;far.GetComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Review+"/Materials/Ground.mat");
  foreach(Transform g in props.Cast<Transform>().ToArray()){if(g.name.StartsWith("grass"))Object.DestroyImmediate(g.gameObject);}
  var parent=new GameObject("MountZone"+id.ToString("00"));zone.transform.SetParent(parent.transform,true);grass.gameObject.SetActive(true);grass.transform.SetParent(parent.transform,true);grass.enabled=true;grass.renderLayer=30;grass.view=null;grass.hero=null;grass.positions=grass.positions.Where(p=>p.x>minX-22&&p.x<maxX+22).ToArray();
  var marker=parent.AddComponent<MountZoneEnvironment>();marker.zone=id-1;marker.background=sky;marker.grass=grass;
  foreach(var r in scene.GetRootGameObjects())if(r!=parent)Object.DestroyImmediate(r);foreach(var t in parent.GetComponentsInChildren<Transform>(true))t.gameObject.layer=30;parent.SetActive(false);EditorSceneManager.SaveScene(scene,Root+"/Scenes/MountZone"+id.ToString("00")+".unity");AssetDatabase.SaveAssets();
  string result=JsonConvert.SerializeObject(new{id,minX,maxX,groundGrid=width*height,misses,farTriangles=subset.Count/3,grass=grass.positions.Length,skyResolution=256});File.WriteAllText(Work+"/evidence/bake-zone"+id.ToString("00")+".json",result);return result;
  Vector3 Sample(float x){for(int i=1;i<path.Length;i++)if(path[i].x>=x)return Vector3.Lerp(path[i-1],path[i],Mathf.InverseLerp(path[i-1].x,path[i].x,x));return path.Last();}
 }
